// Oeste BlockPricing — Topanga block (v0.4.8).
// A full page section composed from Oeste components, inlined below so
// this file is self-contained. Copy-paste ready. Requires: React 18+,
// Tailwind with dark: variant, JSX transform.
// Requires Topanga tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/topanga/src/blocks.js
// Docs: https://oeste.hiddeninwest.com/topanga/#/blocks/pricing
import React from "react";

const FOCUS = "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#1c1917] dark:focus-visible:outline-[#f5f3ef]";

const TOUCH = "min-h-11";

const BUTTON_VARIANTS = {
  primary: "bg-[#c47d3b] text-[#1c1917] hover:opacity-90 dark:bg-[#db914e] dark:text-[#1c1917]",
  secondary: "border border-[#1c1917]/20 bg-transparent text-[#1c1917] hover:bg-[#1c1917]/5 dark:border-[#f5f3ef]/20 dark:text-[#f5f3ef] dark:hover:bg-[#f5f3ef]/5",
  ghost: "bg-transparent text-[#1c1917] hover:bg-[#1c1917]/5 dark:text-[#f5f3ef] dark:hover:bg-[#f5f3ef]/5",
  danger: "bg-[#a83e22] text-[#f6f4f1] hover:opacity-90 dark:bg-[#e07a52] dark:text-[#121110]",
};

const BUTTON_SIZES = {
  sm: "px-3 py-2 text-sm",
  md: "px-5 py-3 text-base",
  lg: "px-6 py-3.5 text-lg",
};

const BADGE_TONES = {
  neutral: "border-[#1c1917]/20 text-[#1c1917] dark:border-[#f5f3ef]/20 dark:text-[#f5f3ef]",
  accent: "border-[#c47d3b]/40 bg-[#c47d3b]/10 text-[#1c1917] dark:border-[#db914e]/40 dark:bg-[#db914e]/10 dark:text-[#f5f3ef]",
  success: "border-[#2f6b3a]/40 bg-[#2f6b3a]/10 text-[#2f6b3a] dark:border-[#6ba368]/40 dark:bg-[#6ba368]/10 dark:text-[#6ba368]",
  danger: "border-[#a83e22]/40 bg-[#a83e22]/10 text-[#a83e22] dark:border-[#e07a52]/40 dark:bg-[#e07a52]/10 dark:text-[#e07a52]",
};

export function Badge({ children, tone = "neutral" }) {
  return <span className={`inline-flex min-h-8 items-center rounded-full border px-3 py-1 text-xs font-semibold ${BADGE_TONES[tone]}`}>{children}</span>;
}

export function Button({ children, variant = "primary", size = "md", disabled = false, loading = false, type = "button", onClick, icon = null }) {
  return (
    <button
      type={type}
      disabled={disabled || loading}
      onClick={onClick}
      aria-busy={loading || undefined}
      className={`${TOUCH} inline-flex items-center justify-center gap-2 rounded-md font-semibold disabled:cursor-not-allowed disabled:opacity-50 ${BUTTON_VARIANTS[variant]} ${BUTTON_SIZES[size]} ${FOCUS}`}
    >
      {loading ? <span aria-hidden="true">…</span> : icon}
      {children}
    </button>
  );
}

export function Card({ title, children, headingLevel = 3 }) {
  const id = React.useId();
  const Heading = `h${headingLevel}`;
  return (
    <section aria-labelledby={id} className="rounded-lg border border-[#1c1917]/10 bg-[#fcfaf7] p-6 text-[#1c1917] shadow-[0_1px_2px_rgba(28,25,23,0.06)] dark:border-[#f5f3ef]/10 dark:bg-[#1c1917] dark:text-[#f5f3ef]">
      <Heading id={id} className="text-xl font-medium">{title}</Heading>
      <div className="mt-3">{children}</div>
    </section>
  );
}

export function RadioGroup({ legend, name, options = [], value, onChange }) {
  return (
    <fieldset className="m-0 border-0 p-0">
      <legend className="mb-2 text-sm font-medium text-[#1c1917] dark:text-[#f5f3ef]">{legend}</legend>
      {options.map((o) => (
        <label key={o.value} htmlFor={`${name}-${o.value}`} className="flex cursor-pointer items-start gap-3 py-2 text-[#1c1917] dark:text-[#f5f3ef]">
          <input id={`${name}-${o.value}`} type="radio" name={name} value={o.value} checked={value === o.value} onChange={() => onChange(o.value)}
            className={`mt-1 h-5 w-5 shrink-0 accent-[#c47d3b] ${FOCUS}`} />
          <span><span className="block text-sm font-medium">{o.label}</span>{o.description && <span className="mt-0.5 block text-sm text-[#706963] dark:text-[#9e968f]">{o.description}</span>}</span>
        </label>
      ))}
    </fieldset>
  );
}

export function Separator({ orientation = "horizontal", decorative = true }) {
  if (orientation === "vertical") {
    return decorative
      ? <span aria-hidden="true" className="inline-block w-px self-stretch bg-[#1c1917]/10 dark:bg-[#f5f3ef]/10" />
      : <span role="separator" aria-orientation="vertical" className="inline-block w-px self-stretch bg-[#1c1917]/10 dark:bg-[#f5f3ef]/10" />;
  }
  return decorative
    ? <hr aria-hidden="true" className="my-4 border-0 border-t border-[#1c1917]/10 dark:border-[#f5f3ef]/10" />
    : <hr role="separator" aria-orientation="horizontal" className="my-4 border-0 border-t border-[#1c1917]/10 dark:border-[#f5f3ef]/10" />;
}

export function Table({ caption, columns = [], rows = [] }) {
  return (
    <div className="overflow-x-auto">
      <table className="w-full border-collapse text-left">
        <caption className="py-2 text-left text-sm font-medium text-[#1c1917] dark:text-[#f5f3ef]">{caption}</caption>
        <thead>
          <tr>
            {columns.map((c) => (
              <th key={c.key} scope="col" className="border-b border-[#1c1917]/10 px-3 py-3 text-sm font-semibold text-[#1c1917] dark:border-[#f5f3ef]/10 dark:text-[#f5f3ef]">{c.header}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, i) => (
            <tr key={i}>
              {columns.map((c, j) => j === 0
                ? <th key={c.key} scope="row" className="border-b border-[#1c1917]/10 px-3 py-3 font-medium text-[#1c1917] dark:border-[#f5f3ef]/10 dark:text-[#f5f3ef]">{row[c.key]}</th>
                : <td key={c.key} className="border-b border-[#1c1917]/10 px-3 py-3 text-[#1c1917] dark:border-[#f5f3ef]/10 dark:text-[#f5f3ef]">{row[c.key]}</td>)}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export function BlockPricing({ variant = "cards" }) {
  const [period, setPeriod] = React.useState("monthly");
  const plans = [
    { name: "Starter", monthly: 12, annual: 9, audience: "For one person getting organised.", features: ["Up to 5 active projects", "Notes, decisions, and files on one page", "One collaborator per project", "Email support"], recommended: false, action: "Start with Starter" },
    { name: "Studio", monthly: 24, annual: 18, audience: "For small studios working with clients.", features: ["Unlimited active projects", "Client-readable project pages", "Budgets and hour tracking", "Up to 15 seats included", "Priority support"], recommended: true, action: "Start with Studio" },
    { name: "Practice", monthly: 48, annual: 36, audience: "For practices with several teams.", features: ["Everything in Studio", "Multiple workspaces", "Decision archive and exports", "Unlimited seats", "A named support contact"], recommended: false, action: "Start with Practice" },
  ];
  return (
    <section className="bg-[#f6f4f1] px-6 py-16 text-[#1c1917] dark:bg-[#121110] dark:text-[#f5f3ef] lg:px-8 lg:py-24">
      <div className="mx-auto max-w-[1200px]">
        <div className="max-w-[640px]">
          <Badge tone="accent">Pricing</Badge>
          <h2 className="mt-4 text-[1.75rem] font-semibold leading-tight tracking-[-0.025em] lg:text-[2.5rem]">One price per person, every feature included</h2>
          <p className="mt-4 leading-relaxed text-[#706963] dark:text-[#9e968f]">Plans differ by scale, not by which features unlock. Pick the size of your studio; change plans whenever it changes.</p>
        </div>
        <div className="mt-8 max-w-[420px]">
          <RadioGroup legend="Billing period" name="billing-period" value={period} onChange={setPeriod} options={[{ value: "monthly", label: "Monthly" }, { value: "annual", label: "Annual", description: "Annual billing saves 25 percent on every plan." }]} />
        </div>
        <div className="mt-10 grid items-start gap-6 lg:grid-cols-3">
          {plans.map((p) => (
            <Card key={p.name} title={p.name} headingLevel={3}>
              {p.recommended ? (
                <p className="mb-4">
                  <Badge tone="accent">Recommended</Badge>
                </p>
              ) : null}
              <p>
                <span className="text-[2.5rem] font-bold leading-none tracking-[-0.06em]">${period === "monthly" ? p.monthly : p.annual}</span>{" "}
                <span className="text-[#706963] dark:text-[#9e968f]">per person, per month, billed {period === "monthly" ? "monthly" : "annually"}</span>
              </p>
              <p className="mt-3 leading-relaxed text-[#706963] dark:text-[#9e968f]">{p.audience}</p>
              <div className="my-5">
                <Separator />
              </div>
              <ul className="list-none space-y-2 p-0 leading-relaxed">
                {p.features.map((f) => (
                  <li key={f}>{f}</li>
                ))}
              </ul>
              <div className="my-5">
                <Separator />
              </div>
              <Button variant={p.recommended ? "primary" : "secondary"} onClick={() => {}}>{p.action}</Button>
            </Card>
          ))}
        </div>
        <p className="mt-8 text-sm text-[#706963] dark:text-[#9e968f]">Prices in US dollars. Cancel any time; annual plans are refunded pro rata for unused months.</p>
        {variant === "full" ? (
          <div className="mt-12">
            <Table caption="Plan comparison" columns={[{ key: "feature", header: "Feature" }, { key: "starter", header: "Starter" }, { key: "studio", header: "Studio" }, { key: "practice", header: "Practice" }]} rows={[{ feature: "Active projects", starter: "Up to 5", studio: "Unlimited", practice: "Unlimited" }, { feature: "Client-readable pages", starter: "Not included", studio: "Included", practice: "Included" }, { feature: "Budgets and hours", starter: "Not included", studio: "Included", practice: "Included" }, { feature: "Seats included", starter: "1", studio: "Up to 15", practice: "Unlimited" }, { feature: "Decision archive", starter: "Not included", studio: "Not included", practice: "Included" }, { feature: "Support", starter: "Email", studio: "Priority email", practice: "Named contact" }]} />
            <p className="mt-6">
              <a href="#faq" className="font-semibold underline">Questions about plans, answered in the FAQ</a>
            </p>
          </div>
        ) : null}
      </div>
    </section>
  );
}
